import type { ReactNode } from "react";
import type { LucideIcon } from "lucide-react";
import { cn } from "@/lib/utils";

export function SettingsPanel({
  id,
  title,
  description,
  icon: Icon,
  children,
  compact = false,
  danger = false,
}: {
  id: string;
  title: string;
  description?: string;
  icon: LucideIcon;
  children?: ReactNode;
  compact?: boolean;
  danger?: boolean;
}) {
  return (
    <section
      id={id}
      aria-labelledby={`${id}-heading`}
      className={cn(
        "backdrop-blur-sm min-w-0 p-7 border border-solid border-[var(--settings-border)] rounded-[var(--appearance-radius,_24px)] [background:var(--settings-surface)] [scroll-margin-top:24px] [@media(width_<_480px)]:p-5",
        compact && `flex items-center justify-between gap-5 flex-wrap`,
        danger && `border-[var(--settings-danger-card-border)]`,
      )}
    >
      <div
        className={cn(
          "flex items-start gap-3.5",
          compact ? "m-0 flex-[1_1_300px]" : "mb-5",
        )}
      >
        <span
          className={cn(
            "w-10 h-10 inline-grid place-items-center flex-none rounded-[var(--appearance-radius,_12px)]",
            danger
              ? "[background:var(--settings-danger-background)] text-[var(--settings-red)]"
              : "workspace-icon-tile [background:var(--appearance-wash,_var(--color-settings-background-27))] text-[var(--settings-purple)]",
          )}
        >
          <Icon size={20} strokeWidth={1.8} aria-hidden="true" />
        </span>
        <div className="min-w-0">
          <h2
            id={`${id}-heading`}
            tabIndex={-1}
            className="text-[20px] font-extrabold tracking-[-0.025em] leading-[1.2] normal-case"
          >
            {title}
          </h2>
          {description && (
            <p
              className={`mt-1 text-[var(--settings-muted)] text-[14px] leading-[1.65]`}
            >
              {description}
            </p>
          )}
        </div>
      </div>
      {children}
    </section>
  );
}
